CREATE TYPE "Role" AS ENUM ('ADMIN','MANAGER','MEMBER');
CREATE TYPE "ProjectStatus" AS ENUM ('PLANNING','ACTIVE','ON_HOLD','COMPLETED','ARCHIVED');
CREATE TYPE "TaskStatus" AS ENUM ('BACKLOG','TODO','IN_PROGRESS','IN_REVIEW','DONE');
CREATE TYPE "Priority" AS ENUM ('LOW','MEDIUM','HIGH','URGENT');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"name" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Workspace" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"slug" TEXT NOT NULL UNIQUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "WorkspaceMember" ("workspaceId" TEXT NOT NULL,"userId" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'MEMBER',"joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("workspaceId","userId"),FOREIGN KEY("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "WorkspaceInvitation" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL,"email" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'MEMBER',"token" TEXT NOT NULL UNIQUE,"expiresAt" TIMESTAMP(3) NOT NULL,UNIQUE("workspaceId","email"),FOREIGN KEY("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE);
CREATE TABLE "Project" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT NOT NULL DEFAULT '',"status" "ProjectStatus" NOT NULL DEFAULT 'ACTIVE',"priority" "Priority" NOT NULL DEFAULT 'MEDIUM',"ownerId" TEXT NOT NULL,"startDate" TIMESTAMP(3),"deadline" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,FOREIGN KEY("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE);
CREATE TABLE "ProjectMember" ("projectId" TEXT NOT NULL,"userId" TEXT NOT NULL,PRIMARY KEY("projectId","userId"),FOREIGN KEY("projectId") REFERENCES "Project"("id") ON DELETE CASCADE);
CREATE TABLE "Task" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL DEFAULT '',"status" "TaskStatus" NOT NULL DEFAULT 'BACKLOG',"priority" "Priority" NOT NULL DEFAULT 'MEDIUM',"assigneeId" TEXT,"creatorId" TEXT NOT NULL,"startDate" TIMESTAMP(3),"dueDate" TIMESTAMP(3),"estimate" INTEGER,"labels" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,FOREIGN KEY("projectId") REFERENCES "Project"("id") ON DELETE CASCADE,FOREIGN KEY("assigneeId") REFERENCES "User"("id"),FOREIGN KEY("creatorId") REFERENCES "User"("id"));
CREATE TABLE "TaskDependency" ("taskId" TEXT NOT NULL,"dependsOnId" TEXT NOT NULL,PRIMARY KEY("taskId","dependsOnId"),FOREIGN KEY("taskId") REFERENCES "Task"("id") ON DELETE CASCADE,FOREIGN KEY("dependsOnId") REFERENCES "Task"("id") ON DELETE CASCADE);
CREATE TABLE "TaskComment" ("id" TEXT PRIMARY KEY,"taskId" TEXT NOT NULL,"authorId" TEXT NOT NULL,"body" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("taskId") REFERENCES "Task"("id") ON DELETE CASCADE,FOREIGN KEY("authorId") REFERENCES "User"("id"));
CREATE TABLE "ActivityLog" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL,"actorId" TEXT NOT NULL,"action" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("actorId") REFERENCES "User"("id"));
CREATE TABLE "Notification" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"type" TEXT NOT NULL,"message" TEXT NOT NULL,"link" TEXT,"dedupeKey" TEXT UNIQUE,"readAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "PasswordResetToken" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"tokenHash" TEXT NOT NULL UNIQUE,"expiresAt" TIMESTAMP(3) NOT NULL,"usedAt" TIMESTAMP(3),FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE INDEX "WorkspaceMember_userId_idx" ON "WorkspaceMember"("userId"); CREATE INDEX "Project_workspaceId_status_idx" ON "Project"("workspaceId","status"); CREATE INDEX "Task_projectId_status_idx" ON "Task"("projectId","status"); CREATE INDEX "Task_assigneeId_dueDate_idx" ON "Task"("assigneeId","dueDate"); CREATE INDEX "ActivityLog_workspaceId_createdAt_idx" ON "ActivityLog"("workspaceId","createdAt"); CREATE INDEX "Notification_userId_readAt_idx" ON "Notification"("userId","readAt");
